void SSendmsgRtnB32Sop1::execute_impl(amdgpu::Wavefront &wf) {
  uint32_t msg = static_cast<uint32_t>(ssrc0.encoding_value_);
  uint64_t value = 0;
  switch (msg) {
  case 0x83: {
    auto *engine = wf.cu().engine();
    value = engine ? engine->global_time() : 0;
    break;
  }
  case 0x80:
  case 0x81:
  case 0x82:
  case 0x84:
  case 0x85:
  case 0x86:
  case 0x87:
  case 0x88:
  case 0x98:
  default:
    value = 0;
    break;
  }
  if (sdst.size_bits() == 64)
    sdst.write_scalar64(wf, value);
  else
    sdst.write_scalar(wf, static_cast<uint32_t>(value));
}

